diff --git a/solution.mjs b/solution.mjs
new file mode 100644
index 0000000..074f2fd
--- /dev/null
+++ b/solution.mjs
@@ -0,0 +1,9 @@
+export function average(nums) {
+  var total = 0;
+  for (var i = 0; i <= nums.length; i++) {
+    if (nums[i] !== undefined) {
+      total = total + nums[i];
+    }
+  }
+  return total / nums.length;
+}
